const items = $input.all();
const expectedPageId = '974103675777955';

function readableDate(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  // Apify start_date/end_date are Unix timestamps in seconds.
  const date = new Date(Number(value) * 1000);

  if (Number.isNaN(date.getTime())) return null;

  return date.toLocaleString('en-IN', {
    timeZone: 'Asia/Kolkata',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

const cleaned = [];

for (const item of items) {
  const d = item.json;
  const snapshot = d.snapshot ?? {};

  // Verify the target page before including an ad.
  const pageId = String(
    d.page_id ?? snapshot.page_id ?? ''
  );

  if (pageId !== expectedPageId) continue;

  const body = String(
    d['snapshot.body.text'] ??
    snapshot.body?.text ??
    ''
  ).trim();

  const headline = String(
    d['snapshot.title'] ??
    snapshot.title ??
    ''
  ).trim();

  const advertiser = String(
    snapshot.page_name ?? d.page_name ?? ''
  ).trim();

  const adId = String(
    d.ad_archive_id ?? d.ad_id ?? ''
  );

  const cta = String(
    d['snapshot.cta_text'] ??
    snapshot.cta_text ??
    ''
  ).trim();

  const destinationUrl =
    d['snapshot.link_url'] ??
    snapshot.link_url ??
    '';

  const normalizedCopy = `${body} ${headline}`
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

  cleaned.push({
    json: {
      ad_id: adId,
      page_id: pageId,
      advertiser,
      body,
      headline,
      cta,
      destination_url: destinationUrl,
      is_active: d.is_active ?? null,
      start_date: d.start_date ?? null,
      start_date_readable: readableDate(d.start_date),
      end_date: d.end_date ?? null,
      end_date_readable: readableDate(d.end_date),
      creative_group: normalizedCopy,
      hook: '',
      page_verified: true
    }
  });
}

return cleaned;

const items = $input.all();

// Retrieve the original ad records from Clean Code Node.
// Match each AI result to its original ad using ad_id.
const originalItems = $('Clean code Node').all();

const originalById = new Map();

for (const item of originalItems) {
  const d = item.json;
  const id = String(d.ad_id ?? '');

  if (id) {
    originalById.set(id, d);
  }
}

return items.map((item, index) => {
  const raw =
    item.json.text ??
    item.json.response ??
    item.json.output;

  if (typeof raw !== 'string') {
    throw new Error(
      `Item ${index + 1}: AI response text is missing`
    );
  }

  const cleaned = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  let parsed;

  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      `Item ${index + 1}: Invalid AI JSON: ${error.message}`
    );
  }

  const adId = String(parsed.ad_id ?? '');
  const original = originalById.get(adId);

  if (!original) {
    throw new Error(
      `Item ${index + 1}: Original ad not found for ID ${adId}`
    );
  }

  const scoreFields = [
    'hook_strength',
    'pain_point_relevance',
    'value_proposition_score',
    'cta_clarity',
    'differentiation'
  ];

  for (const field of scoreFields) {
    const score = Number(parsed[field]);

    if (!Number.isFinite(score) || score < 1 || score > 10) {
      throw new Error(
        `Item ${index + 1}: Invalid ${field} score`
      );
    }

    parsed[field] = score;
  }

  return {
    json: {
      ...original,
      ...parsed,

      // Preserve the source ad ID and original copy.
      source_ad_id: adId,
      original_body: String(original.body ?? ''),
      original_headline: String(original.headline ?? ''),
      original_cta: String(original.cta ?? ''),
      original_destination_url: String(
        original.destination_url ?? ''
      )
    }
  };
});

const items = $input.all();

// Keep the highest-scoring record for each unique text creative.
const groups = new Map();

for (const item of items) {
  const d = item.json;

  const copy = [
    d.original_body ?? d.body,
    d.original_headline ?? d.headline
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

  if (!copy) continue;

  const scores = [
    Number(d.hook_strength),
    Number(d.pain_point_relevance),
    Number(d.value_proposition_score),
    Number(d.cta_clarity),
    Number(d.differentiation)
  ];

  if (scores.some(s => !Number.isFinite(s) || s < 1 || s > 10)) {
    throw new Error(`Invalid score for ad ${d.ad_id}`);
  }

  const score = Math.round((
    scores[0] * 2.5 +
    scores[1] * 2 +
    scores[2] * 2 +
    scores[3] * 1.5 +
    scores[4] * 2
  ) * 10) / 10;

  const existing = groups.get(copy);

  const record = {
    ...d,
    creative_quality_score: score
  };

  if (!existing || score > existing.creative_quality_score) {
    groups.set(copy, {
      ...record,
      duplicate_ad_ids: existing
        ? [...(existing.duplicate_ad_ids ?? []), existing.ad_id]
        : []
    });
  } else {
    existing.duplicate_ad_ids.push(d.ad_id);
  }
}

const ranked = [...groups.values()]
  .sort((a, b) =>
    b.creative_quality_score - a.creative_quality_score
  )
  .map((d, index) => ({
    json: {
      ...d,
      creative_rank: index + 1,
      is_top_creative: index === 0,
      ranking_basis: 'AI-assessed text-creative quality, not campaign performance'
    }
  }));

return ranked;

const items = $input.all();
const groups = new Map();

for (const item of items) {
  const d = item.json;

  const copy = [
  d.original_body ?? d.body,
  d.original_headline ?? d.headline
]
  .filter(Boolean)
  .join(' ')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

  // Do not group records when no usable text exists.
  const key = copy || `ad-${d.ad_id ?? d.source_ad_id ?? groups.size}`;

  if (!groups.has(key)) {
    groups.set(key, {
      ...d,
      source_ad_id: d.source_ad_id ?? d.ad_id ?? '',
      duplicate_ad_ids: []
    });
  } else {
    const existing = groups.get(key);
    const currentId = String(d.source_ad_id ?? d.ad_id ?? '');

    if (
      currentId &&
      currentId !== String(existing.source_ad_id) &&
      !existing.duplicate_ad_ids.includes(currentId)
    ) {
      existing.duplicate_ad_ids.push(currentId);
    }

    if (
      Number(d.creative_quality_score) >
      Number(existing.creative_quality_score)
    ) {
      const duplicateIds = existing.duplicate_ad_ids;
      groups.set(key, {
        ...d,
        source_ad_id: d.source_ad_id ?? d.ad_id ?? '',
        duplicate_ad_ids: duplicateIds
      });
    }
  }
}

const ranked = [...groups.values()].sort(
  (a, b) =>
    Number(b.creative_quality_score) -
    Number(a.creative_quality_score)
);

return ranked.map((ad, index) => ({
  json: {
    ...ad,
    creative_rank: index + 1,
    is_top_creative: index === 0,
    ranking_basis:
      'AI-assessed creative quality; not campaign performance'
  }
}));

const items = $input.all().map(item => item.json);

if (items.length === 0) {
  throw new Error('No ranked ads received. Execute the previous nodes first.');
}

const ranked = [...items].sort(
  (a, b) => Number(a.creative_rank) - Number(b.creative_rank)
);

const winner = ranked.find(ad => ad.is_top_creative === true) ?? ranked[0];

const uniqueCreatives = ranked.map(ad => ({
  rank: Number(ad.creative_rank),
  ad_id: String(ad.source_ad_id ?? ad.ad_id ?? ''),
  language: ad.language ?? 'Not identified',
  score: Number(ad.creative_quality_score),
  hook: ad.hook ?? 'Not identified',
  headline: ad.original_headline ?? ad.headline ?? '',
  body: ad.original_body ?? ad.body ?? '',
  cta: ad.original_cta ?? ad.cta ?? '',
  strength: ad.strength ?? '',
  weakness: ad.weakness ?? '',
  improvement: ad.improvement ?? '',
  duplicate_ad_ids: ad.duplicate_ad_ids ?? [],
  is_winner: ad.is_top_creative === true
}));

return [{
  json: {
    report_title: 'MySivi Facebook Ads Creative Analysis',
    advertiser: winner.advertiser ?? 'MySivi Spoken English App',
    generated_at: new Date().toISOString(),
    source_ad_records_analyzed: 10,
    unique_text_creatives_ranked: uniqueCreatives.length,
    winner: {
      ad_id: String(winner.source_ad_id ?? winner.ad_id ?? ''),
      language: winner.language ?? 'Not identified',
      creative_quality_score: Number(winner.creative_quality_score),
      hook: winner.hook ?? '',
      headline: winner.original_headline ?? winner.headline ?? '',
      body: winner.original_body ?? winner.body ?? '',
      cta: winner.original_cta ?? winner.cta ?? '',
      strength: winner.strength ?? '',
      weakness: winner.weakness ?? '',
      improvement: winner.improvement ?? '',
      destination_url: winner.original_destination_url ?? winner.destination_url ?? ''
    },
    ranked_creatives: uniqueCreatives,
    scoring_methodology: {
      scale: '1-10 per category',
      weights: {
        hook_strength: '25%',
        pain_point_relevance: '20%',
        value_proposition_score: '20%',
        cta_clarity: '15%',
        differentiation: '20%'
      },
      interpretation: 'AI-assessed text creative quality; not measured campaign performance.'
    },
    limitations: [
      'No impressions, clicks, installs, spend, conversion rate, or ROAS data was supplied.',
      'Ranking evaluates ad copy and AI-assessed creative quality, not actual campaign performance.',
      'Repeated ads are grouped using normalized original body copy and headline.',
      'Visual creative quality cannot be assessed unless the ad images or videos are analyzed.'
    ],
    recommendations: [
      'Test specific, relatable situations where learners need spoken English.',
      'Explain how the AI tutor helps users practise, rather than relying only on broad ease-of-learning claims.',
      'Make the ₹1 trial offer and next action clear in the ad.',
      'Validate creative hypotheses using actual campaign results before reallocating advertising spend.'
    ]
  }
}];
